const response = await fetch("http://127.0.0.1:8000/predict", {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    area: "Hazratganj",
    hour: 10,
    day_of_week: 2,
    is_holiday: 0,
    weather: "Clear",
    temperature: 30,
    vehicle_count: 180,
    num_lanes: 4,
  }),
});

const result = await response.json();
console.log(result);
